import React, {Component} from 'react';
import { NavLink } from 'react-router-dom';

export default class NavigationBar extends Component {

    constructor(props) {
        super(props);
        this.state = { isOpen: false };
        this.toggle = this.toggle.bind(this);
    }

    toggle() {
        this.setState({isOpen: !this.state.isOpen});
    }

    render() {
        return (
            <nav className="nav-terminal">
                <div className="container">
                    <a className="nav-brand" href="/">
                        ~/vishal-chand <span>Software Developer</span>
                    </a>
                    <button className="nav-toggle" onClick={this.toggle}>
                        <i className="fa fa-bars"/>
                    </button>
                    <ul className={"nav-links" + (this.state.isOpen ? " open" : "")}>
                        <li><NavLink to="/home" activeClassName="active">home</NavLink></li>
                        <li><NavLink to="/cv" activeClassName="active">resume</NavLink></li>
                        <li><NavLink to="/projects" activeClassName="active">projects</NavLink></li>
                        <li><NavLink to="/blog" activeClassName="active">blog</NavLink></li>
                    </ul>
                </div>
            </nav>
        );    
    }
}
